#include <format>
#include <iostream>

struct Temperature {
    double celsius;
};

template<>
struct std::formatter<Temperature> {
    constexpr auto parse(std::format_parse_context& context) {
        auto it = context.begin();
        while (it != context.end() && *it != '}') {
            ++it;                       // accept and ignore any spec
        }
        return it;
    }

    auto format(const Temperature& temp,
                std::format_context& context) const {
        return std::format_to(context.out(), "{:.1f}C", temp.celsius);
    }
};

int main() {
    std::cout << std::format("[{:>8}][{:>8}]",
                             Temperature{21.5}, "21.5C") << '\n';
}

