#include <cstddef>
#include <cstdint>
#include <iomanip>
#include <ios>
#include <ostream>
#include <span>

class FormatGuard {
public:
    explicit FormatGuard(std::ostream& out)
        : out_{out}, flags_{out.flags()}, fill_{out.fill()} {}

    // Restoring in a destructor is what makes this exception-safe: an
    // insertion that throws still leaves the caller's stream alone.
    ~FormatGuard() {
        out_.flags(flags_);
        out_.fill(fill_);
    }

    FormatGuard(const FormatGuard&) = delete;
    FormatGuard& operator=(const FormatGuard&) = delete;

private:
    std::ostream& out_;
    std::ios::fmtflags flags_;
    char fill_;
};

void hexdump_row(std::ostream& out, std::span<const std::uint8_t> bytes) {
    FormatGuard guard{out};
    out << std::hex << std::setfill('0');

    for (std::size_t i = 0; i < bytes.size(); ++i) {
        if (i != 0) {
            out << ' ';
        }
        // Width is consumed by the next insertion and resets to zero, so
        // it is set per byte -- unlike hex and the fill character, which
        // stay until something changes them. The cast matters too: a
        // std::uint8_t inserts as a character, not as a number.
        out << std::setw(2) << static_cast<unsigned>(bytes[i]);
    }
}

#include <charconv>
#include <istream>
#include <map>
#include <string>
#include <string_view>
#include <system_error>

namespace {

std::string_view trim(std::string_view text) {
    const auto first = text.find_first_not_of(" \t");
    if (first == std::string_view::npos) {
        return {};
    }
    return text.substr(first, text.find_last_not_of(" \t") - first + 1);
}

}  // namespace

std::map<std::string, double> load_thresholds(std::istream& in) {
    std::map<std::string, double> thresholds;
    std::string line;

    while (std::getline(in, line)) {
        std::string_view view{line};

        // getline splits on '\n' and leaves the '\r' of a CRLF file at
        // the end of the line, where it would poison the last field.
        if (!view.empty() && view.back() == '\r') {
            view.remove_suffix(1);
        }

        const auto comment = view.find('#');
        if (comment != std::string_view::npos) {
            view = view.substr(0, comment);
        }

        const auto equals = view.find('=');
        if (equals == std::string_view::npos) {
            continue;   // blank or malformed line
        }

        const std::string_view name = trim(view.substr(0, equals));
        const std::string_view field = trim(view.substr(equals + 1));

        double value = 0.0;
        const char* end = field.data() + field.size();
        auto [next, error] = std::from_chars(field.data(), end, value);

        // Both conditions are needed: from_chars happily parses the
        // leading number of "1.5kg" and reports success.
        if (name.empty() || error != std::errc{} || next != end) {
            continue;
        }

        thresholds.insert_or_assign(std::string{name}, value);
    }

    return thresholds;
}

#include <cstdint>
#include <format>
#include <string>

struct Bytes {
    std::uint64_t count;
};

// Inheriting the string formatter inherits its parse, and with it fill,
// alignment, width and precision -- all already specified, tested and
// familiar to the caller. Re-implementing them here would be a second
// dialect of the same syntax that drifts from the standard one.
template<>
struct std::formatter<Bytes> : std::formatter<std::string> {
    auto format(Bytes value, std::format_context& context) const {
        double scaled = static_cast<double>(value.count);
        const char* unit = "B";

        if (scaled >= 1024.0) {
            scaled /= 1024.0;
            unit = "KiB";
        }
        if (scaled >= 1024.0) {
            scaled /= 1024.0;
            unit = "MiB";
        }

        const std::string text = (unit[0] == 'B')
            ? std::format("{} B", value.count)
            : std::format("{:.1f} {}", scaled, unit);

        // The base class applies whatever the caller asked for.
        return std::formatter<std::string>::format(text, context);
    }
};

#include <array>
#include <cstddef>
#include <cstdint>
#include <format>
#include <string_view>

struct Row {
    std::array<char, 64> bytes;
    std::size_t size;
    bool truncated;
};

Row make_row(std::string_view actor, std::string_view action,
             std::int64_t object_id) {
    Row row{};

    auto result = std::format_to_n(
        row.bytes.begin(), row.bytes.size(),
        "actor={} action={} object={}", actor, action, object_id);

    // result.size is what the complete record *needed*; result.out is
    // where writing actually stopped. Confusing the two is how a row
    // ends up claiming a length past the end of its own storage.
    row.size = static_cast<std::size_t>(result.out - row.bytes.begin());
    row.truncated = result.size > static_cast<std::ptrdiff_t>(row.bytes.size());

    // Nothing appended a terminator: `size` is the record boundary, and
    // the reader must be handed a length, not a char*.
    return row;
}

#include <istream>
#include <string>
#include <utility>

std::pair<double, int> total(std::istream& in) {
    double sum = 0.0;
    int skipped = 0;

    for (;;) {
        double value = 0.0;
        if (in >> value) {
            sum += value;
            continue;
        }

        // Distinguish the three ways an extraction stops. Only a parse
        // failure is recoverable: end of input is done, and badbit means
        // the device is gone, not that this token was odd.
        if (in.eof() || in.bad()) {
            break;
        }

        in.clear();

        std::string token;
        if (!(in >> token)) {
            break;
        }
        ++skipped;

        // Consuming the token is what guarantees progress. Clearing the
        // state without it leaves the same character in the buffer and
        // the loop spins forever on the first word.
    }

    return {sum, skipped};
}

#include <chrono>
#include <cstdint>
#include <cstdio>
#include <format>
#include <iterator>
#include <string>
#include <vector>

struct FrameEvent {
    std::chrono::steady_clock::time_point at;
    std::uint32_t site;
    double a;
    std::uint32_t b;
};

class FrameLog {
public:
    explicit FrameLog(std::size_t capacity) : slots_(capacity) {}

    // A clock read and four stores. No format, no allocation, no write:
    // whatever this costs, it costs the same on every frame.
    bool record(std::uint32_t site, double a, std::uint32_t b) noexcept {
        if (used_ == slots_.size()) {
            ++dropped_;   // counted, not silent
            return false;
        }
        slots_[used_++] = {std::chrono::steady_clock::now(), site, a, b};
        return true;
    }

    std::uint64_t dropped() const noexcept { return dropped_; }

    void drain(std::FILE* out) {
        // One buffer for the whole drain: clear() keeps the capacity, so
        // after the first few events no further allocation happens.
        std::string line;

        for (std::size_t i = 0; i < used_; ++i) {
            const FrameEvent& event = slots_[i];
            line.clear();
            std::format_to(std::back_inserter(line),
                           "site={} a={:.3f} b={}\n",
                           event.site, event.a, event.b);
            std::fwrite(line.data(), 1, line.size(), out);
        }

        used_ = 0;   // the next frame starts from an empty buffer
    }

private:
    std::vector<FrameEvent> slots_;
    std::size_t used_ = 0;
    std::uint64_t dropped_ = 0;
};
